#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <openssl/sha.h>
#include <openssl/rand.h>

#define MAX_SESSIONS 1024
#define TOKEN_LEN 32
#define MAX_ROLES 8

typedef struct {
    uint8_t token[TOKEN_LEN];
    char username[64];
    int role_count;
    char roles[MAX_ROLES][32];
    volatile int valid;
    volatile int ref_count;
} Session;

static Session sessions[MAX_SESSIONS];
static pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize session store
void init_sessions(void) {
    memset(sessions, 0, sizeof(sessions));
}

// Create a new session
int create_session(const char *username, const char *role) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!sessions[i].valid) {
            // Verify the CSPRNG succeeded; a failed RAND_bytes could leave
            // predictable/uninitialized token data.
            if (RAND_bytes(sessions[i].token, TOKEN_LEN) != 1) {
                pthread_mutex_unlock(&session_lock);
                return -1;
            }
            strncpy(sessions[i].username, username, 63);
            sessions[i].username[63] = '\0';
            sessions[i].role_count = 1;
            strncpy(sessions[i].roles[0], role, 31);
            sessions[i].roles[0][31] = '\0';
            sessions[i].ref_count = 0;
            sessions[i].valid = 1;
            pthread_mutex_unlock(&session_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return -1;
}

// Invalidate session (logout)
void destroy_session(int idx) {
    if (idx < 0 || idx >= MAX_SESSIONS) return;
    pthread_mutex_lock(&session_lock);
    sessions[idx].valid = 0;
    // Wait for references to drain
    while (sessions[idx].ref_count > 0) {
        pthread_mutex_unlock(&session_lock);
        usleep(1000);
        pthread_mutex_lock(&session_lock);
    }
    memset(&sessions[idx], 0, sizeof(Session));
    pthread_mutex_unlock(&session_lock);
}

// Find session by token - returns index or -1
// NOTE: We acquire a reference to prevent use-after-free
int find_session(const uint8_t *token) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].valid && memcmp(sessions[i].token, token, TOKEN_LEN) == 0) {
            sessions[i].ref_count++;
            pthread_mutex_unlock(&session_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return -1;
}

void release_session(int idx) {
    if (idx < 0 || idx >= MAX_SESSIONS) return;
    __sync_fetch_and_sub(&sessions[idx].ref_count, 1);
}

// Check if session has a specific role
// Uses role_index parameter for efficient lookup when caller knows the index
int session_has_role(int session_idx, const char *role, int role_hint) {
    if (session_idx < 0 || session_idx >= MAX_SESSIONS) return 0;
    Session *s = &sessions[session_idx];

    // Fast path: if caller provides a valid hint index, check it first
    // role_hint is provided by the URL routing layer as a signed int
    if (role_hint >= 0 && role_hint < s->role_count) {
        if (strcmp(s->roles[role_hint], role) == 0) return 1;
    }

    // Slow path: linear scan
    for (int i = 0; i < s->role_count; i++) {
        if (strcmp(s->roles[i], role) == 0) return 1;
    }
    return 0;
}

// Parse role_hint from request header
// X-Role-Hint: <integer>
int parse_role_hint(const char *header_value) {
    if (!header_value) return -1;
    // Parse as long to detect overflow, then cast
    long val = strtol(header_value, NULL, 10);
    // Security check: must be within valid role range
    if (val < 0 || val >= MAX_ROLES) return -1;
    return (int)val;
}

// Authorization check for admin endpoint
int check_admin_access(int session_idx, int role_hint) {
    return session_has_role(session_idx, "admin", role_hint);
}

// Simulated request handler
typedef struct {
    uint8_t token[TOKEN_LEN];
    char path[256];
    int role_hint;
} Request;

void handle_request(Request *req) {
    int sid = find_session(req->token);
    if (sid < 0) {
        printf("401 Unauthorized\n");
        return;
    }

    if (strncmp(req->path, "/admin", 6) == 0) {
        if (check_admin_access(sid, req->role_hint)) {
            printf("200 OK - Admin access granted for %s\n", sessions[sid].username);
        } else {
            printf("403 Forbidden\n");
        }
    } else {
        printf("200 OK\n");
    }

    release_session(sid);
}

// Background session cleanup thread
void *cleanup_thread(void *arg) {
    (void)arg;
    while (1) {
        sleep(60);
        pthread_mutex_lock(&session_lock);
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (sessions[i].valid && sessions[i].ref_count == 0) {
                // Expired session cleanup logic would go here
            }
        }
        pthread_mutex_unlock(&session_lock);
    }
    return NULL;
}

int main(void) {
    init_sessions();

    pthread_t cleanup;
    pthread_create(&cleanup, NULL, cleanup_thread, NULL);

    // Demo: create a regular user session
    int sid = create_session("alice", "user");
    if (sid < 0) {
        printf("Failed to create session\n");
        return 1;
    }
    printf("Created session %d for alice\n", sid);

    // Simulate normal request
    Request req;
    memcpy(req.token, sessions[sid].token, TOKEN_LEN);
    strcpy(req.path, "/admin");
    req.role_hint = -1;  // No hint
    handle_request(&req);

    // Simulate request with valid hint
    req.role_hint = parse_role_hint("0");
    handle_request(&req);

    destroy_session(sid);
    return 0;
}
